import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';
import { UserHttpService } from '../user-http.service';

export interface Flight {
  _id: string;
  dataOra: string;
  duration: number;
  // aggiungi altri campi se serve
}

export interface LayoverConnection {
  layover: string;
  firstLeg: Flight;
  secondLeg: Flight;
}

@Injectable({
  providedIn: 'root'
})
export class FlightSearchService {

  constructor(private http: HttpClient, private us : UserHttpService) { }

  searchFlights(depart: string, destination: string): Observable<any[]/*Flight[] | LayoverConnection[]*/> {
    let params = new HttpParams()
      .set('depart', depart)
      .set('destination', destination);

    return this.http.get<any[]/*Flight[] | LayoverConnection[]*/>(this.us.url + '/search', { params });
  }
}
